pragma solidity 0.8.25;

import "openzeppelin-contracts-5.0/access/Ownable.sol";
import "openzeppelin-contracts-5.0/utils/structs/EnumerableSet.sol";
import "./AuctionError.sol";
import "./IAuctionFeeVault.sol";

contract AuctionFeeVault is IAuctionFeeVault, Ownable, AuctionError {
    using EnumerableSet for EnumerableSet.AddressSet;

    /* ========== STATE VARIABLES ========== */

    EnumerableSet.AddressSet private _bidTakers;
    mapping(address => uint256) private _bidTaken;

    uint256 public accumulatedBids;

    /* ========== CONSTRUCTOR ========== */

    constructor(address initialOwner) Ownable(initialOwner) {}

    /* ========== FEE MANAGEMENT ========== */

    /// @dev Receive KAIA from the auction deposit vault
    /// @notice Sending KAIA to this contract is same as donating to the protocol
    receive() external payable override {
        _bidTakers.add(block.coinbase);
        _bidTaken[block.coinbase] += msg.value;

        accumulatedBids += msg.value;

        emit FeeDeposit(block.coinbase, msg.value);
    }

    /// @dev Withdraw KAIA from the vault
    /// @param addrs The addresses to withdraw to
    /// @param amounts The amounts to withdraw
    function withdraw(address[] calldata addrs, uint256[] calldata amounts) external override onlyOwner {
        if (addrs.length != amounts.length) revert InvalidInput();

        uint256 totalAmount = 0;
        for (uint256 i = 0; i < addrs.length; ) {
            (bool success, ) = addrs[i].call{value: amounts[i]}("");
            if (!success) revert WithdrawalFailed();
            unchecked {
                totalAmount += amounts[i];
                i++;
            }
        }

        emit FeeWithdrawal(totalAmount);
    }

    /* ========== GETTERS ========== */

    function getBidTaken(address addr) external view override returns (uint256) {
        return _bidTaken[addr];
    }

    function getBidTakerInfo(
        uint256 start,
        uint256 limit
    ) external view override returns (address[] memory bidTakers, uint256[] memory bidTaken) {
        uint256 totalAddresses = _bidTakers.length();
        uint256 end;
        if (limit == 0) {
            end = totalAddresses;
        } else {
            end = start + limit > totalAddresses ? totalAddresses : start + limit;
        }

        bidTakers = new address[](end - start);
        bidTaken = new uint256[](end - start);
        for (uint256 i = start; i < end; ) {
            address _bidTaker = _bidTakers.at(i);
            bidTakers[i - start] = _bidTaker;
            bidTaken[i - start] = _bidTaken[_bidTaker];
            unchecked {
                i++;
            }
        }
    }
}

